package com.example.pointage.ui.home;

import android.os.Handler;
import android.os.Looper;
import android.util.Log;

import androidx.lifecycle.LiveData;
import androidx.lifecycle.MutableLiveData;
import androidx.lifecycle.ViewModel;

import com.example.pointage.SupabaseClient;
import com.example.pointage.ui.historique.DateUtils;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;

import java.net.UnknownHostException;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Calendar;
import java.util.Collections;
import java.util.Date;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class HomeViewModel extends ViewModel {

    private static final String TAG = "HomeViewModel";
    private final MutableLiveData<String> mText;
    private final MutableLiveData<List<Notification>> notificationsLiveData = new MutableLiveData<>();
    private final SupabaseClient supabaseClient;

    // Auto-refresh
    private final Handler refreshHandler = new Handler(Looper.getMainLooper());
    private final long refreshIntervalMs = 30_000; // 30 secondes
    private volatile boolean isLoading = false;

    private final Runnable refreshRunnable = new Runnable() {
        @Override
        public void run() {
            loadNotifications();
            refreshHandler.postDelayed(this, refreshIntervalMs);
        }
    };

    public HomeViewModel() throws UnknownHostException {
        mText = new MutableLiveData<>();
        mText.setValue("POINTAGES DES SURVEILLANTS DE L'ENI");
        supabaseClient = SupabaseClient.getInstance();

        // Supprimer les anciennes notifications (plus de 60 jours)
        deleteOldNotifications();

        // Charger les notifications initiales
        loadNotifications();

        // Démarrer l'auto-refresh
        refreshHandler.postDelayed(refreshRunnable, refreshIntervalMs);
    }

    public LiveData<String> getText() {
        return mText;
    }

    public LiveData<List<Notification>> getNotifications() {
        return notificationsLiveData;
    }

    public void loadNotifications() {
        if (isLoading) {
            Log.d(TAG, "Skip refresh: still loading");
            return;
        }
        isLoading = true;

        final List<Notification> notifications = new ArrayList<>();
        final Map<Long, String> surveillantNameById = new HashMap<>();
        final Map<Long, String> surveillantRoomById = new HashMap<>();

        // Calculer la date limite (60 jours en arrière)
        Calendar limitCal = Calendar.getInstance();
        limitCal.add(Calendar.DAY_OF_MONTH, -60);
        final Date limitDate = limitCal.getTime();

        // 1️⃣ Récupérer tous les surveillants
        supabaseClient.select("surveillant", "*", null, new SupabaseClient.SupabaseCallback() {
            @Override
            public void onSuccess(JsonArray surveillantResult) {
                try {
                    for (int i = 0; i < surveillantResult.size(); i++) {
                        JsonObject surveillantDoc = surveillantResult.get(i).getAsJsonObject();
                        Long surveillantId = surveillantDoc.get("id_surveillant").getAsLong();
                        String nomSurveillant = surveillantDoc.get("nom_surveillant").getAsString();

                        surveillantNameById.put(surveillantId, nomSurveillant);
                    }

                    // 2️⃣ Récupérer les salles depuis planning_surveillance
                    loadSurveillantRoomsFromPlanning(notifications, surveillantNameById, surveillantRoomById, limitDate);

                } catch (Exception e) {
                    Log.e(TAG, "Error processing surveillants", e);
                    isLoading = false;
                }
            }

            @Override
            public void onError(Exception error) {
                Log.e(TAG, "Error loading surveillants", error);
                isLoading = false;
            }
        });
    }

    private void loadSurveillantRoomsFromPlanning(List<Notification> notifications,
                                                  Map<Long, String> surveillantNameById,
                                                  Map<Long, String> surveillantRoomById,
                                                  Date limitDate) {
        // Récupérer les affectations surveillant/salle depuis planning_surveillance
        supabaseClient.select("planning_surveillance", "*", null, new SupabaseClient.SupabaseCallback() {
            @Override
            public void onSuccess(JsonArray planningResult) {
                try {
                    for (int i = 0; i < planningResult.size(); i++) {
                        JsonObject planningDoc = planningResult.get(i).getAsJsonObject();
                        if (!planningDoc.has("id_surveillant") || planningDoc.get("id_surveillant").isJsonNull()) {
                            continue;
                        }
                        Long surveillantId = planningDoc.get("id_surveillant").getAsLong();

                        if (!surveillantNameById.containsKey(surveillantId)) {
                            continue; // Surveillant inconnu
                        }

                        if (planningDoc.has("numero_salle") && !planningDoc.get("numero_salle").isJsonNull()) {
                            String numeroSalle = planningDoc.get("numero_salle").getAsString();
                            if (numeroSalle != null && !numeroSalle.trim().isEmpty()) {
                                surveillantRoomById.put(surveillantId, numeroSalle.trim());
                            }
                        }
                    }

                    loadPointageNotifications(notifications, surveillantNameById, surveillantRoomById, limitDate);

                } catch (Exception e) {
                    Log.e(TAG, "Error processing planning_surveillance", e);
                    isLoading = false;
                }
            }

            @Override
            public void onError(Exception error) {
                Log.e(TAG, "Error loading planning_surveillance", error);
                isLoading = false;
            }
        });
    }

    private void loadPointageNotifications(List<Notification> notifications,
                                           Map<Long, String> surveillantNameById,
                                           Map<Long, String> surveillantRoomById,
                                           Date limitDate) {
        supabaseClient.select("pointage", "*", "order=heure_pointage.desc&limit=150",
                new SupabaseClient.SupabaseCallback() {
                    @Override
                    public void onSuccess(JsonArray pointageResult) {
                        try {
                            for (int i = 0; i < pointageResult.size(); i++) {
                                JsonObject pointageDoc = pointageResult.get(i).getAsJsonObject();

                                Long idSurveillant = pointageDoc.get("id_surveillant").getAsLong();
                                boolean retard = pointageDoc.get("retard").getAsBoolean();

                                String heurePointageStr = pointageDoc.get("heure_pointage").getAsString();
                                Date heurePointage;
                                try {
                                    heurePointage = DateUtils.parseSupabaseTimestamp(heurePointageStr);
                                } catch (ParseException e) {
                                    Log.w(TAG, "Failed to parse heure_pointage: " + heurePointageStr, e);
                                    continue;
                                }

                                String nomSurveillant = surveillantNameById.get(idSurveillant);
                                String numeroSalle = null;

                                if (surveillantRoomById.containsKey(idSurveillant)) {
                                    numeroSalle = surveillantRoomById.get(idSurveillant);
                                } else if (pointageDoc.has("numero_salle") && !pointageDoc.get("numero_salle").isJsonNull()) {
                                    String numeroSalleFromPointage = pointageDoc.get("numero_salle").getAsString();
                                    if (numeroSalleFromPointage != null && !numeroSalleFromPointage.trim().isEmpty()) {
                                        numeroSalle = numeroSalleFromPointage.trim();
                                        surveillantRoomById.put(idSurveillant, numeroSalle);
                                    }
                                }

                                // Filtrer les notifications de plus de 60 jours
                                if (nomSurveillant != null && heurePointage.after(limitDate)) {
                                    String notificationType = retard ? "retard" : "presence";

                                    Notification notification = new Notification(
                                            pointageDoc.has("id_pointage") ? pointageDoc.get("id_pointage").getAsLong() : null,
                                            nomSurveillant,
                                            notificationType,
                                            heurePointage,
                                            numeroSalle
                                    );
                                    notifications.add(notification);
                                }
                            }

                            // 3️⃣ Récupérer les sanctions récentes pour les absences
                            loadAbsenceNotifications(notifications, surveillantNameById, surveillantRoomById, limitDate);

                        } catch (Exception e) {
                            Log.e(TAG, "Error processing pointages", e);
                            isLoading = false;
                        }
                    }

                    @Override
                    public void onError(Exception error) {
                        Log.e(TAG, "Error loading pointages", error);
                        isLoading = false;
                    }
                });
    }

    private void calculateAbsencesFromExams(List<Notification> notifications,
                                            List<JsonObject> exams,
                                            Map<Long, String> surveillantNameById,
                                            Map<Long, String> surveillantRoomById,
                                            Map<Long, Map<String, Set<Long>>> pointagesByDaySession,
                                            Map<Long, Map<String, Set<String>>> pointagesRoomsByDaySession,
                                            Date limitDate) {
        for (JsonObject exam : exams) {
            String heureDebutStr = exam.get("heure_debut").getAsString();
            Date heureDebut;
            try {
                heureDebut = DateUtils.parseSupabaseTimestamp(heureDebutStr);
            } catch (ParseException e) {
                Log.w(TAG, "Failed to parse heure_debut for absence calculation: " + heureDebutStr, e);
                continue;
            }

            if (heureDebut.before(limitDate)) continue;

            Calendar heureDebCal = Calendar.getInstance();
            heureDebCal.setTime(heureDebut);
            Calendar examDay = getStartOfDay(heureDebut);
            long dayMillis = examDay.getTimeInMillis();
            String session = (heureDebCal.get(Calendar.HOUR_OF_DAY) < 12) ? "Matin" : "Après-midi";

            String examRoom = null;
            if (exam.has("numero_salle_resolved") && !exam.get("numero_salle_resolved").isJsonNull()) {
                examRoom = exam.get("numero_salle_resolved").getAsString();
            }
            if (examRoom == null) continue;
            examRoom = examRoom.trim();

            Long surveillantId = null;
            if (exam.has("id_surveillant") && !exam.get("id_surveillant").isJsonNull()) {
                try {
                    surveillantId = exam.get("id_surveillant").getAsLong();
                } catch (Exception ignored) {
                    surveillantId = null;
                }
            }
            if (surveillantId == null) {
                for (Map.Entry<Long, String> entry : surveillantRoomById.entrySet()) {
                    if (examRoom.equalsIgnoreCase(entry.getValue())) {
                        surveillantId = entry.getKey();
                        break;
                    }
                }
            }
            if (surveillantId == null) continue;

            if (!hasPointageForSession(pointagesByDaySession, pointagesRoomsByDaySession,
                    dayMillis, session, surveillantId, examRoom)) {
                String nomSurveillant = surveillantNameById.get(surveillantId);
                if (nomSurveillant != null) {
                    Notification notification = new Notification(null, nomSurveillant, "absence", heureDebut, examRoom);
                    notifications.add(notification);
                }
            }
        }
    }

    private void calculateAbsencesFromPlanning(List<Notification> notifications, Map<Long, String> surveillantNameById, Map<Long, String> surveillantRoomById, Map<Long, Map<String, Set<Long>>> pointagesByDaySession, Map<Long, Map<String, Set<String>>> pointagesRoomsByDaySession, Date limitDate) {
        supabaseClient.select("planning_surveillance", "*", "date_examen=gte." + DateUtils.formatForSupabase(limitDate), new SupabaseClient.SupabaseCallback() {
            @Override
            public void onSuccess(JsonArray planningResult) {
                try {
                    for (int i = 0; i < planningResult.size(); i++) {
                        JsonObject planning = planningResult.get(i).getAsJsonObject();
                        if (!planning.has("id_surveillant") || planning.get("id_surveillant").isJsonNull()) continue;
                        Long surveillantId = planning.get("id_surveillant").getAsLong();
                        String nomSurveillant = surveillantNameById.get(surveillantId);
                        if (nomSurveillant == null) continue;
                        String room = null;
                        if (planning.has("numero_salle") && !planning.get("numero_salle").isJsonNull()) {
                            room = planning.get("numero_salle").getAsString().trim();
                        }
                        if (room == null) continue;
                        // Assume planning has date_examen
                        String dateStr = planning.get("date_examen").getAsString();
                        Date date;
                        try {
                            date = DateUtils.parseSupabaseTimestamp(dateStr);
                        } catch (ParseException e) {
                            Log.w(TAG, "Failed to parse date_examen for planning absence: " + dateStr, e);
                            continue;
                        }
                        Calendar cal = getStartOfDay(date);
                        long dayMillis = cal.getTimeInMillis();
                        String session = (cal.get(Calendar.HOUR_OF_DAY) < 12) ? "Matin" : "Après-midi";
                        if (!hasPointageForSession(pointagesByDaySession, pointagesRoomsByDaySession, dayMillis, session, surveillantId, room)) {
                            Notification notification = new Notification(null, nomSurveillant, "absence", date, room);
                            notifications.add(notification);
                        }
                    }
                    // Calculer les absences à partir des examens (fallback)
                    loadExamAbsenceData(notifications, surveillantNameById, surveillantRoomById,
                            pointagesByDaySession, pointagesRoomsByDaySession, limitDate);
                } catch (Exception e) {
                    Log.e(TAG, "Error processing planning for absences", e);
                    // Even if processing failed, try exams
                    loadExamAbsenceData(notifications, surveillantNameById, surveillantRoomById,
                            pointagesByDaySession, pointagesRoomsByDaySession, limitDate);
                }
            }
            @Override
            public void onError(Exception error) {
                Log.e(TAG, "Error loading planning_surveillance for absences", error);
                // Try exams even if planning failed
                loadExamAbsenceData(notifications, surveillantNameById, surveillantRoomById,
                        pointagesByDaySession, pointagesRoomsByDaySession, limitDate);
            }
        });
    }

    private void loadExamAbsenceData(List<Notification> notifications,
                                     Map<Long, String> surveillantNameById,
                                     Map<Long, String> surveillantRoomById,
                                     Map<Long, Map<String, Set<Long>>> pointagesByDaySession,
                                     Map<Long, Map<String, Set<String>>> pointagesRoomsByDaySession,
                                     Date limitDate) {
        supabaseClient.select("examen", "*", "heure_debut=gte." + DateUtils.formatForSupabase(limitDate), new SupabaseClient.SupabaseCallback() {
            @Override
            public void onSuccess(JsonArray examResult) {
                List<JsonObject> exams = new ArrayList<>();
                for (int i = 0; i < examResult.size(); i++) {
                    exams.add(examResult.get(i).getAsJsonObject());
                }
                calculateAbsencesFromExams(notifications, exams, surveillantNameById, surveillantRoomById,
                        pointagesByDaySession, pointagesRoomsByDaySession, limitDate);
                finalizeNotificationUpdate(notifications);
            }

            @Override
            public void onError(Exception error) {
                Log.e(TAG, "Error loading exams for absences", error);
                finalizeNotificationUpdate(notifications);
            }
        });
    }

    private boolean hasPointageForSession(Map<Long, Map<String, Set<Long>>> pointagesByDaySession,
                                          Map<Long, Map<String, Set<String>>> pointagesRoomsByDaySession,
                                          long dayMillis,
                                          String session,
                                          Long surveillantId,
                                          String room) {
        if (pointagesRoomsByDaySession.containsKey(dayMillis)) {
            Map<String, Set<String>> sessionRoomsMap = pointagesRoomsByDaySession.get(dayMillis);
            if (sessionRoomsMap.containsKey(session)) {
                for (String checkedRoom : sessionRoomsMap.get(session)) {
                    if (checkedRoom.equalsIgnoreCase(room)) {
                        return true;
                    }
                }
            }
        }

        if (pointagesByDaySession.containsKey(dayMillis)) {
            Map<String, Set<Long>> sessionMap = pointagesByDaySession.get(dayMillis);
            if (sessionMap.containsKey(session) && sessionMap.get(session).contains(surveillantId)) {
                return true;
            }
        }
        return false;
    }

    private Calendar getStartOfDay(Date date) {
        Calendar cal = Calendar.getInstance();
        cal.setTime(date);
        cal.set(Calendar.HOUR_OF_DAY, 0);
        cal.set(Calendar.MINUTE, 0);
        cal.set(Calendar.SECOND, 0);
        cal.set(Calendar.MILLISECOND, 0);
        return cal;
    }

    private void loadAbsenceNotifications(List<Notification> notifications,
                                          Map<Long, String> surveillantNameById,
                                          Map<Long, String> surveillantRoomById,
                                          Date limitDate) {
        // Charger les pointages pour grouper par jour et session
        supabaseClient.select("pointage", "*", "heure_pointage=gte." + DateUtils.formatForSupabase(limitDate), new SupabaseClient.SupabaseCallback() {
            @Override
            public void onSuccess(JsonArray pointageResult) {
                Map<Long, Map<String, Set<Long>>> pointagesByDaySession = new HashMap<>();
                Map<Long, Map<String, Set<String>>> pointagesRoomsByDaySession = new HashMap<>();
                try {
                    for (int i = 0; i < pointageResult.size(); i++) {
                        JsonObject pointageDoc = pointageResult.get(i).getAsJsonObject();
                        Long idSurveillant = pointageDoc.get("id_surveillant").getAsLong();
                        String heurePointageStr = pointageDoc.get("heure_pointage").getAsString();
                        Date heurePointage = DateUtils.parseSupabaseTimestamp(heurePointageStr);

                        Calendar heurePointageCal = Calendar.getInstance();
                        heurePointageCal.setTime(heurePointage);
                        Calendar dayStartCal = getStartOfDay(heurePointage);
                        long dayMillis = dayStartCal.getTimeInMillis();
                        String session = (heurePointageCal.get(Calendar.HOUR_OF_DAY) < 12) ? "Matin" : "Après-midi";

                        pointagesByDaySession
                                .computeIfAbsent(dayMillis, k -> new HashMap<>())
                                .computeIfAbsent(session, k -> new HashSet<>())
                                .add(idSurveillant);

                        String pointageRoom = null;
                        if (surveillantRoomById.containsKey(idSurveillant)) {
                            pointageRoom = surveillantRoomById.get(idSurveillant);
                        } else if (pointageDoc.has("numero_salle") && !pointageDoc.get("numero_salle").isJsonNull()) {
                            String numeroSalleFromPointage = pointageDoc.get("numero_salle").getAsString();
                            if (numeroSalleFromPointage != null && !numeroSalleFromPointage.trim().isEmpty()) {
                                pointageRoom = numeroSalleFromPointage.trim();
                                surveillantRoomById.put(idSurveillant, pointageRoom);
                            }
                        }

                        if (pointageRoom != null && !pointageRoom.trim().isEmpty()) {
                            String finalRoom = pointageRoom.trim();
                            pointagesRoomsByDaySession
                                    .computeIfAbsent(dayMillis, k -> new HashMap<>())
                                    .computeIfAbsent(session, k -> new HashSet<>())
                                    .add(finalRoom);
                        }
                    }

                    // Calculer les absences à partir de planning_surveillance
                    calculateAbsencesFromPlanning(notifications, surveillantNameById, surveillantRoomById,
                            pointagesByDaySession, pointagesRoomsByDaySession, limitDate);

                } catch (Exception e) {
                    Log.e(TAG, "Erreur lors du traitement des pointages pour les absences", e);
                    finalizeNotificationUpdate(notifications);
                }
            }

            @Override
            public void onError(Exception error) {
                Log.e(TAG, "Erreur lors du chargement des pointages pour les absences", error);
                finalizeNotificationUpdate(notifications);
            }
        });
    }

    private void finalizeNotificationUpdate(List<Notification> notifications) {
        // Trier les notifications par date décroissante
        Collections.sort(notifications, (a, b) -> b.getDateHeure().compareTo(a.getDateHeure()));

        // Garder seulement les 60 dernières notifications
        if (notifications.size() > 60) {
            notifications.subList(60, notifications.size()).clear();
        }

        // Mettre à jour les données LiveData
        notificationsLiveData.postValue(notifications);
        isLoading = false;
    }

    /**
     * Supprime les notifications de plus de 60 jours de la base de données
     */
    private void deleteOldNotifications() {
        Calendar limitCal = Calendar.getInstance();
        limitCal.add(Calendar.DAY_OF_MONTH, -60);
        String limitDateStr = DateUtils.formatForSupabase(limitCal.getTime());

        Log.d(TAG, "Suppression des notifications antérieures à: " + limitDateStr);

        // Supprimer les anciens pointages (plus de 60 jours)
        String pointageFilter = "heure_pointage=lt." + limitDateStr;
        supabaseClient.delete("pointage", pointageFilter, new SupabaseClient.SupabaseCallback() {
            @Override
            public void onSuccess(JsonArray result) {
                Log.d(TAG, "Anciens pointages supprimés avec succès");
            }

            @Override
            public void onError(Exception error) {
                Log.e(TAG, "Erreur lors de la suppression des anciens pointages", error);
            }
        });

        // Supprimer les anciennes sanctions (plus de 60 jours)
        String sanctionFilter = "date_sanction=lt." + limitDateStr;
        supabaseClient.delete("sanction", sanctionFilter, new SupabaseClient.SupabaseCallback() {
            @Override
            public void onSuccess(JsonArray result) {
                Log.d(TAG, "Anciennes sanctions supprimées avec succès");
            }

            @Override
            public void onError(Exception error) {
                Log.e(TAG, "Erreur lors de la suppression des anciennes sanctions", error);
            }
        });
    }

    @Override
    protected void onCleared() {
        super.onCleared();
        // Arrêter l'auto-refresh
        refreshHandler.removeCallbacks(refreshRunnable);
    }
}
